// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t) public {
        // Any timestamp works as long as the first call passes the time check
        t = bound(t, 1, type(uint256).max / 4);

        // First call at time t succeeds (pastBlockTime starts at 0)
        vm.warp(t);
        vm.deal(address(this), 10 ether);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // General rule: a call that succeeded at time t implies a call at time t+2
        // must also succeed. Reference: pastBlockTime = t+1, and t+2 > t+1 holds.
        // Mutant: pastBlockTime = t+2, and t+2 > t+2 fails, so the call reverts.
        vm.warp(t + 2);
        vm.deal(address(this), 10 ether);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2, "a call two seconds after a successful call must succeed");
    }
}
